const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Polygon([[
    [-83.13, 43.25], // NW corner (West of Lake Erie)
    [-73.5, 43.25],  // NE corner (Upstate NY)
    [-73.5, 41.5],   // SE corner (Southern NY)
    [-83.13, 41.5]   // SW corner (South of Lake Erie)
  ]]);

  const date1 = '2020-02-22';
  const date2 = '2020-03-01';

  // 2. Data Acquisition & Processing Function
  const getSnowArea = function(dateString) {
    const imageCollection = ee.ImageCollection('MODIS/061/MOD10A1')
      .filterDate(dateString, ee.Date(dateString).advance(1, 'day'))
      .filterBounds(aoi);

    // Check for image availability
    if (imageCollection.size().getInfo() === 0) {
      return {error: 'C1', date: dateString};
    }

    const image = imageCollection.first();

    // Mask for good quality, clear pixels
    const qcMask = image.select('MODIS_QC').bitwiseAnd(0b11).eq(0); // Bit 0=good, Bit 1=clear

    // Create a binary mask for snow pixels (NDSI_Snow_Cover > 15%)
    const snow = image.select('NDSI_Snow_Cover').gt(15);
    const snowMasked = snow.updateMask(snow.and(qcMask));

    // Calculate pixel counts
    const totalPixels = image.updateMask(qcMask).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
    }).get('NDSI_Snow_Cover');

    const snowPixels = snowMasked.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: 1000,
        maxPixels: 1e9
    }).get('NDSI_Snow_Cover');

    return {
      total: totalPixels.getInfo(),
      snow: snowPixels.getInfo(),
      date: dateString
    };
  };

  // 3. Calculation for both dates
  const result1 = getSnowArea(date1);
  const result2 = getSnowArea(date2);

  // 4. Validation & Final Answer
  if (result1.error === 'C1' || result2.error === 'C1') {
    console.log(`No images found for: ${result1.error ? result1.date : ''} ${result2.error ? result2.date : ''}`);
    console.log('C1');
    return;
  }

  if (result1.total === 0 || result2.total === 0) {
    console.log(`No valid (cloud-free) pixels for Feb 22, 2020: ${result1.total}`);
    console.log(`No valid (cloud-free) pixels for Mar 01, 2020: ${result2.total}`);
    console.log('C2');
    return;
  }

  // Check for null/None results from reduction
  if (result1.snow === null || result2.snow === null) {
      console.log(`Calculation failed. Snow pixels for Feb 22: ${result1.snow}, Mar 01: ${result2.snow}`);
      console.log('C3');
      return;
  }

  const snowArea1 = result1.snow;
  const snowArea2 = result2.snow;

  console.log(`Feb 22, 2020: Snow Pixels = ${snowArea1} (out of ${result1.total} valid pixels)`);
  console.log(`Mar 01, 2020: Snow Pixels = ${snowArea2} (out of ${result2.total} valid pixels)`);

  if (snowArea2 > snowArea1) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  try {
      await runAnalysis();
  } catch(e) {
      console.error(e);
      console.log('D');
  }
}

initEE();
